// Flatten each hiring company into sheet columns.
const today = new Date().toISOString().slice(0, 10);
return $input.all().map(i => i.json).filter(c => c.company).map(c => ({ json: {
  date: today,
  company: c.company,
  linkedin: c.companyUrl || '',
  jobs_found: c.jobsFound,
  posted_last_7_days: c.postedLast7Days,
  posted_last_30_days: c.postedLast30Days,
  remote_jobs: c.remoteJobs,
  ai_jobs: c.aiJobs,
  titles: (c.sampleTitles || []).slice(0, 5).join(' | '),
  locations: Object.keys(c.topLocations || {}).join(' | '),
  first_job: (c.jobUrls || [])[0] || '',
} }));
